    { name: "אריה לייב שפירא",     text: "הושעיה היה מפעיל בלונים בחתונה שלנו, וזה היה מדהים. הגיע עם בלונים מוכנים מראש ועם המכונה להוסיף עוד. חוויה מדהימה, הילדים נהנו המבוגרים נהנו. הכל במקצועיות ורוחב לב, ממליצים בחום", photo: "", screenshot: "" },
    { name: "עינב צברי",           text: "הזמנו את הושעיה לעצב את הבת-מצווה. במקצועיות ומיומנות מדהימה המועדון הפך לאולם אירועים יפהפה. חילק כתרים מבלונים מעוצבים, שידרג את האירוע ברמות. ממליצה בחום!", photo: "", screenshot: "" },
    { name: "שירה כהן",            text: "תודה רבה! נהנינו מאוד! גם הקטנים וגם הגדולים!", photo: "", screenshot: "" },
    { name: "עידן יוסף וניצן ליבן", text: "תודה רבה על ערב בלתי נשכח, הבלונים שדרגו אותו מאוד בצבעם ובייחודם. כשרון מהמם וכולם מהקטנטנים ועד הגדולים נהנו מאוד", photo: "", screenshot: "" },
    { name: "משפחת ארביט",         text: "הבלונים שעשית היו מקסימים, כל הכבוד אתה מקצוען", photo: "", screenshot: "" },
    { name: "יגל ויסכה שרעבי",     text: "הושעיה המוכשר עשה לנו פשוט שמח בבר מצווה! מלא סבלנות, עשה מלא כובעים ודמויות לפי בקשות. ממליצים בחום!", photo: "", screenshot: "" },
    { name: "איתן ויפעת חובב",     text: "ממליצה בחום! שידרג לנו את הבר מצווה. הכל היה מוכן בזמן. מענה מהיר וזמינות. מחכים כבר לאירוע הבא!", photo: "", screenshot: "" }
